def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_def = op.count('D')
    my_def = my.count('D')
    last_me, last_opp = history[-1]
    remaining = 100 - n

    # Break mutual defection spiral
    if n >= 2 and my[-1] == 'D' and op[-1] == 'D' and my[-2] == 'D' and op[-2] == 'D':
        return 'C'

    # Endgame: defect in the very last round
    if remaining <= 1:
        return 'D'

    # Early game
    if n < 4:
        if opp_def == n:
            return 'D'
        return 'C'

    # Avoid over-exploiting: if we have defected much more than opponent, cooperate
    if n >= 8 and my_def > opp_def + 2:
        return 'C'

    # Core TFT with forgiveness for single defections
    if last_opp == 'D':
        # Forgive only if opponent's previous action was C (single defection) and overall defection rate is low
        if n >= 2 and op[-2] == 'C' and opp_def <= n * 0.2:
            if rng.random() < 0.5:
                return 'C'
        return 'D'
    else:
        return 'C'
